export class Unique {
  private readonly values = new Map<string, number>();
  add(key: string, value: number): void {
    this.values.set(key, (this.values.get(key) ?? 0) + value);
  }
  report(): string[] {
    return [...this.values].map(([k, v]) => `${k}=${v}`);
  }
}
